                let HandleValue::PytorchTensorTensor(arg_1_value) = &arg_1_entry.value else { return protocol_error("handle_type_mismatch", "pytorch.Tensor.Tensor"); };
                let arg_1_ref = arg_1_value.as_ref().expect("validated non-null handle");
